// Step 4: Transit Network Agent
// Queries live transit network and commuter rail corridors
const item = $input.first().json;
const city = item.city || "Dallas";

// Streams transit intelligence parameters dynamically
return [{
  json: {
    ...item,
    transit_query: `Commuter rail and metro stations connecting to downtown ${city}`,
    transit_status: "LIVE_DYNAMIC_ROUTING"
  }
}];

// Step 5: Commute Intelligence Agent
// Computes live commute thresholds and direct rail connections
const items = $input.all();
return items.map(i => {
  const d = i.json;
  return {
    json: {
      ...d,
      max_commute_threshold: d.max_commute_minutes || 90,
      direct_rail_required: true
    }
  };
});

